<?php require_once __DIR__ . '/../bootstrap.php'; require_auth('admin'); if($_SERVER['REQUEST_METHOD']==='GET'){$search='%'.($_GET['search']??'').'%';$s=$pdo->prepare('SELECT id,full_name,username,email,role,status,created_at,last_login FROM users WHERE full_name LIKE ? OR email LIKE ? OR username LIKE ? ORDER BY created_at DESC');$s->execute([$search,$search,$search]);respond(true,'',['users'=>$s->fetchAll()]);}$i=body();$id=(int)($i['id']??0);if($id===$_SESSION['user']['id'])respond(false,'You cannot change your own administrator access.',[],422);$s=$pdo->prepare('UPDATE users SET role=?,status=? WHERE id=?');$s->execute([$i['role']??'user',$i['status']??'active',$id]);respond(true,'User updated successfully.');
